using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieve a configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["app_name"] = "McpHttpServer",
            ["version"] = "1.0.0",
            ["environment"] = "production",
            ["max_connections"] = "100"
        };

        return config.TryGetValue(key, out var value)
            ? value
            : $"Unknown key: {key}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Full application configuration as JSON")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "production",
            MaxConnections = 100,
            Features = new { CachingEnabled = true, RateLimitPerMinute = 60 }
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Available API endpoint definitions")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Method = "POST", Description = "MCP Streamable HTTP endpoint" },
            new { Path = "/health", Method = "GET", Description = "Health check" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

